window.docContents[21].resolve({"/Airy-and-Related-Functions/Chapter-contents/#LMLF-___-DLMF-with-Lean--Airy-and-Related-Functions--Chapter-contents":{"contents":"\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Airy and Related Functions","header":"Chapter contents","id":"/Airy-and-Related-Functions/Chapter-contents/#LMLF-___-DLMF-with-Lean--Airy-and-Related-Functions--Chapter-contents"},"/Elementary-Functions/___4___27-Sums/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___27-Sums--___4___27-Sums":{"contents":"Source: DLMF §4.27.\n\nSection 4.27 is a reference section rather than a formula section.  It\ncontains no numbered equations, tables, figures, or additional displayed\nidentities.  For sums of trigonometric and inverse-trigonometric functions,\nthe DLMF points readers to the following standard compendia:\n\n* Gradshteyn and Ryzhik (2015), Chapter 1;* Hansen (1975), §§14–42;* Oberhettinger (1973); and* Prudnikov et al. (1986a), Chapter 5.\n\nThe neighboring DLMF sections provide the mathematical source context:\n§4.26 Integrals precedes this bibliography, and\n§4.28 Definitions and Periodicity follows it.\nSince the source contributes bibliography only, this page records that prose\ndirectly and introduces no mathematical declaration or quantitative companion.\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.27 Sums","header":"§4.27 Sums","id":"/Elementary-Functions/___4___27-Sums/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___27-Sums--___4___27-Sums"}});